// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

// ================================================================
// AYRMockOracle — Price Oracle for AYR Swap Router
//
// Stores USD prices for each supported asset (8 decimal precision,
// matching Chainlink's format). Owner updates prices from the node
// process which polls CoinGecko every 60s.
//
// In production this would be replaced with a decentralised oracle
// (Chainlink / Pyth). For now it's owner-controlled.
//
// Prices: USD value with 8 decimals
//   e.g. BTC = $84,000 → stored as 8_400_000_000_000 (84000 * 1e8)
// ================================================================

contract AYRMockOracle {

    address public owner;

    // symbol => USD price (8 decimals)
    mapping(string => uint256) private prices;
    // symbol => last update timestamp
    mapping(string => uint256) public lastUpdated;
    // Authorized updaters (node hot wallet)
    mapping(address => bool)   public updaters;

    // Staleness threshold: 10 minutes
    uint256 public constant STALE_AFTER = 600;

    event PriceUpdated(string indexed symbol, uint256 price, uint256 timestamp);
    event UpdaterChanged(address updater, bool status);

    modifier onlyOwner() {
        require(msg.sender == owner, "Oracle: not owner");
        _;
    }

    modifier onlyUpdater() {
        require(updaters[msg.sender] || msg.sender == owner, "Oracle: not updater");
        _;
    }

    constructor() {
        owner = msg.sender;
        updaters[msg.sender] = true;

        // Seed reasonable initial prices so SwapRouter works immediately
        // Node process will overwrite these with live data within 60s
        _setPrice("BTC",   8_400_000_000_000); // $84,000
        _setPrice("ETH",   2_000_000_000_000); // $2,000
        _setPrice("SOL",      14_000_000_000); // $140
        _setPrice("BNB",     600_000_000_000); // $600
        _setPrice("MATIC",     100_000_000_0); // $0.10 — note: 8 decimals, $0.10 = 10_000_000
        _setPrice("ARB",       100_000_000_0); // $1.00 = 100_000_000
        _setPrice("AYR",       100_000_000_0); // $1.00 synthetic peg
    }

    function _setPrice(string memory symbol, uint256 price) internal {
        prices[symbol]      = price;
        lastUpdated[symbol] = block.timestamp;
    }

    // ── Admin ──────────────────────────────────────────────────────

    function setUpdater(address updater, bool status) external onlyOwner {
        updaters[updater] = status;
        emit UpdaterChanged(updater, status);
    }

    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "Oracle: zero address");
        owner = newOwner;
    }

    // ── Price updates ─────────────────────────────────────────────

    function setPrice(string calldata symbol, uint256 price) external onlyUpdater {
        require(price > 0, "Oracle: zero price");
        _setPrice(symbol, price);
        emit PriceUpdated(symbol, price, block.timestamp);
    }

    // Batch update — used by node process to push all prices in one tx
    function setPrices(
        string[]  calldata symbols,
        uint256[] calldata newPrices
    ) external onlyUpdater {
        require(symbols.length == newPrices.length, "Oracle: length mismatch");
        for (uint i = 0; i < symbols.length; i++) {
            require(newPrices[i] > 0, "Oracle: zero price");
            _setPrice(symbols[i], newPrices[i]);
            emit PriceUpdated(symbols[i], newPrices[i], block.timestamp);
        }
    }

    // ── Read ──────────────────────────────────────────────────────

    // Returns price in USD with 8 decimals.
    // Returns 0 if price is stale (> STALE_AFTER seconds old).
    function getPrice(string calldata symbol) external view returns (uint256) {
        if (block.timestamp - lastUpdated[symbol] > STALE_AFTER) return 0;
        return prices[symbol];
    }

    // Returns price without staleness check (for read-only display)
    function getPriceRaw(string calldata symbol) external view returns (uint256 price, uint256 age) {
        price = prices[symbol];
        age   = block.timestamp - lastUpdated[symbol];
    }

    function isStale(string calldata symbol) external view returns (bool) {
        return block.timestamp - lastUpdated[symbol] > STALE_AFTER;
    }
}

contracts/AYRStaking.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

// ================================================================
// AYRStaking — Native AYR Validator Staking
//
// AYR is the NATIVE currency of chain 210078, not an ERC-20.
// Validators stake native AYR via msg.value (no approval needed).
//
// Rules:
//   - Minimum stake: 1,000 AYR
//   - Max validators: 21
//   - Unbond period: 7 days (enforced via block.timestamp)
//   - Slash penalty: 50% of stake, locked in contract
//   - Only owner can slash (the authority node)
//
// Frontend call:
//   staking.stake({ value: ethers.parseEther(amount), gasLimit: 200000 })
// ================================================================

contract AYRStaking {

    uint256 public constant MIN_STAKE      = 1_000 ether;  // 1000 AYR
    uint256 public constant MAX_VALIDATORS = 21;
    uint256 public constant UNBOND_PERIOD  = 7 days;

    address public owner;

    struct Validator {
        uint256 stake;
        uint256 since;          // block number when staked
        uint256 unbondAt;       // timestamp after which can withdraw (0 = not unbonding)
        bool    active;
        bool    slashed;
    }

    address[]                        public validatorList;
    mapping(address => Validator)    public validators;
    // Slashed AYR accumulates here (not withdrawable — effectively burned)
    uint256                          public slashedPool;

    event ValidatorRegistered(address indexed validator, uint256 stake, uint256 blockNumber);
    event UnbondRequested(address indexed validator, uint256 unlockAt);
    event Withdrawn(address indexed validator, uint256 amount);
    event Slashed(address indexed validator, uint256 penalty);
    event TopUpStake(address indexed validator, uint256 added, uint256 total);

    modifier onlyOwner() {
        require(msg.sender == owner, "Staking: not owner");
        _;
    }

    constructor() {
        owner = msg.sender;
    }

    // ── Core: Stake ───────────────────────────────────────────────
    // Send native AYR as msg.value to register/top-up as validator.
    // Matches frontend: staking.stake({ value: parseEther(amount) })
    function stake() external payable {
        require(msg.value > 0, "Staking: zero value");
        require(!validators[msg.sender].slashed, "Staking: address is slashed");

        Validator storage v = validators[msg.sender];
        uint256 newTotal = v.stake + msg.value;
        require(newTotal >= MIN_STAKE, "Staking: below minimum 1000 AYR");

        bool isNew = (v.stake == 0);
        if (isNew) {
            require(activeCount() < MAX_VALIDATORS, "Staking: validator slots full");
            validatorList.push(msg.sender);
            v.since = block.number;
            emit ValidatorRegistered(msg.sender, newTotal, block.number);
        } else {
            emit TopUpStake(msg.sender, msg.value, newTotal);
        }

        v.stake   = newTotal;
        v.active  = true;
        v.unbondAt = 0; // cancel any pending unbond
    }

    // ── Core: Request Unbond ──────────────────────────────────────
    // Starts the 7-day countdown. Validator stays active until
    // withdraw() is called after the period.
    function requestUnbond() external {
        Validator storage v = validators[msg.sender];
        require(v.active, "Staking: not active");
        require(v.unbondAt == 0, "Staking: unbond already requested");
        v.unbondAt = block.timestamp + UNBOND_PERIOD;
        v.active   = false;
        emit UnbondRequested(msg.sender, v.unbondAt);
    }

    // ── Core: Withdraw ────────────────────────────────────────────
    // Sends stake back after unbond period has elapsed.
    function withdraw() external {
        Validator storage v = validators[msg.sender];
        require(!v.active, "Staking: still active - call requestUnbond first");
        require(!v.slashed, "Staking: slashed");
        require(v.unbondAt > 0, "Staking: no unbond pending");
        require(block.timestamp >= v.unbondAt, "Staking: unbond period not over");
        require(v.stake > 0, "Staking: nothing to withdraw");

        uint256 amount = v.stake;
        v.stake   = 0;
        v.unbondAt = 0;

        (bool ok, ) = msg.sender.call{value: amount}("");
        require(ok, "Staking: transfer failed");
        emit Withdrawn(msg.sender, amount);
    }

    // ── Admin: Slash ──────────────────────────────────────────────
    // Owner (authority node) slashes 50% of a misbehaving validator.
    // Slashed AYR stays locked in contract.
    function slash(address validator) external onlyOwner {
        Validator storage v = validators[validator];
        require(v.active || v.unbondAt > 0, "Staking: not staked");
        require(!v.slashed, "Staking: already slashed");

        uint256 penalty = v.stake / 2;
        v.stake   -= penalty;
        v.active   = false;
        v.slashed  = true;
        v.unbondAt = 0;
        slashedPool += penalty;

        emit Slashed(validator, penalty);
    }

    // ── Views ─────────────────────────────────────────────────────

    function activeCount() public view returns (uint256 count) {
        for (uint i = 0; i < validatorList.length; i++) {
            if (validators[validatorList[i]].active) count++;
        }
    }

    function getActiveValidators() external view returns (address[] memory addrs, uint256[] memory stakes) {
        uint256 n = activeCount();
        addrs  = new address[](n);
        stakes = new uint256[](n);
        uint256 idx;
        for (uint i = 0; i < validatorList.length; i++) {
            address a = validatorList[i];
            if (validators[a].active) {
                addrs[idx]  = a;
                stakes[idx] = validators[a].stake;
                idx++;
            }
        }
    }

    function validatorCount() external view returns (uint256) {
        return activeCount();
    }

    // Total AYR locked in this contract
    function totalStaked() external view returns (uint256) {
        return address(this).balance - slashedPool;
    }

    receive() external payable {}
}

contracts/AYRSwapRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

// ================================================================
// AYRSwapRouter — Oracle-Priced Cross-Chain Swap Router
//
// Architecture:
//   - No liquidity pools. Oracle prices everything.
//   - Swaps burn fromAsset wrapped token and mint toAsset.
//   - bridgeIn/bridgeOut are called by the relayer node.
//   - All assets are wrapped ERC-20 tokens (wETH, wSOL, etc.)
//   - Bitcoin uses the UTXORegistry (native, no wrapping).
//
// Frontend ABI (matching AYR.tsx handleSwap):
//   swap(fromAsset, toAsset, amountIn, minAmountOut) — ERC20→ERC20
//   bridgeIn(asset, recipient, amount, sourceTxHash) — relayer only
//   bridgeOut(asset, amount, destinationAddress)     — user exits
//   getQuote(fromAsset, toAsset, amountIn)           — view
// ================================================================

interface IERC20Mintable {
    function mint(address to, uint256 amount) external;
    function burn(address from, uint256 amount) external;
    function balanceOf(address) external view returns (uint256);
    function transfer(address, uint256) external returns (bool);
    function transferFrom(address, address, uint256) external returns (bool);
    function approve(address, uint256) external returns (bool);
}

interface IOracle {
    function getPrice(string calldata symbol) external view returns (uint256);
}

contract AYRSwapRouter {

    address public owner;
    IOracle public oracle;

    // Fee: 0.1% = 10 basis points
    uint256 public feeBps = 10;
    address public feeCollector;

    mapping(string  => address) public wrappedTokens;
    mapping(string  => bool)    public supportedAssets;
    mapping(bytes32 => bool)    public processedTxs;
    mapping(address => bool)    public relayers;

    uint256 private _lock = 1;

    modifier onlyOwner()    { require(msg.sender == owner, "Router: not owner"); _; }
    modifier onlyRelayer()  { require(relayers[msg.sender], "Router: not relayer"); _; }
    modifier nonReentrant() { require(_lock == 1, "Router: reentrant"); _lock = 2; _; _lock = 1; }

    event SwapExecuted(address indexed user, string fromAsset, string toAsset, uint256 amountIn, uint256 amountOut);
    event BridgeIn(address indexed to, string asset, uint256 amount, bytes32 sourceTxHash);
    event BridgeOut(address indexed from, string asset, uint256 amount, string destinationAddress);
    event AssetRegistered(string symbol, address token);
    event RelayerUpdated(address relayer, bool status);

    // ── Constructor ───────────────────────────────────────────────
    // _oracle:       AYRMockOracle address
    // _feeCollector: address that receives swap fees
    constructor(address _oracle, address _feeCollector) {
        require(_oracle != address(0),       "Router: zero oracle");
        require(_feeCollector != address(0), "Router: zero feeCollector");
        owner        = msg.sender;
        oracle       = IOracle(_oracle);
        feeCollector = _feeCollector;
        relayers[msg.sender] = true;
    }

    // ── Admin ──────────────────────────────────────────────────────

    function registerAsset(string calldata symbol, address tokenContract) external onlyOwner {
        wrappedTokens[symbol]   = tokenContract;
        supportedAssets[symbol] = true;
        emit AssetRegistered(symbol, tokenContract);
    }

    function setRelayer(address relayer, bool status) external onlyOwner {
        relayers[relayer] = status;
        emit RelayerUpdated(relayer, status);
    }

    function setFee(uint256 bps) external onlyOwner {
        require(bps <= 100, "Router: max 1%");
        feeBps = bps;
    }

    function setOracle(address _oracle) external onlyOwner {
        oracle = IOracle(_oracle);
    }

    function setFeeCollector(address _fc) external onlyOwner {
        feeCollector = _fc;
    }

    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "Router: zero address");
        owner = newOwner;
    }

    // ── Bridge In ─────────────────────────────────────────────────
    // Relayer confirms deposit on source chain and mints wrapped token.
    function bridgeIn(
        string  calldata asset,
        address          recipient,
        uint256          amount,
        bytes32          sourceTxHash
    ) external onlyRelayer nonReentrant {
        require(supportedAssets[asset],         "Router: asset not supported");
        require(!processedTxs[sourceTxHash],    "Router: already processed");
        require(amount > 0,                     "Router: zero amount");
        processedTxs[sourceTxHash] = true;

        uint256 fee       = (amount * feeBps) / 10_000;
        uint256 netAmount = amount - fee;

        IERC20Mintable token = IERC20Mintable(wrappedTokens[asset]);
        token.mint(recipient, netAmount);
        if (fee > 0) token.mint(feeCollector, fee);

        emit BridgeIn(recipient, asset, netAmount, sourceTxHash);
    }

    // ── Swap ──────────────────────────────────────────────────────
    // Burns fromAsset, mints toAsset at oracle price.
    // User must have approved the fromAsset token first.
    // Called by frontend: router.swap(fromAsset, toAsset, amountIn, minAmountOut)
    function swap(
        string  calldata fromAsset,
        string  calldata toAsset,
        uint256          amountIn,
        uint256          minAmountOut
    ) external nonReentrant returns (uint256 amountOut) {
        require(supportedAssets[fromAsset], "Router: from not supported");
        require(supportedAssets[toAsset],   "Router: to not supported");
        require(amountIn > 0,               "Router: zero amount");

        uint256 fromPrice = oracle.getPrice(fromAsset);
        uint256 toPrice   = oracle.getPrice(toAsset);
        require(fromPrice > 0, "Router: stale fromAsset price");
        require(toPrice   > 0, "Router: stale toAsset price");

        // Burn fromAsset from user
        IERC20Mintable fromToken = IERC20Mintable(wrappedTokens[fromAsset]);
        fromToken.burn(msg.sender, amountIn);

        // amountOut = amountIn * fromPrice / toPrice
        uint256 raw  = (amountIn * fromPrice) / toPrice;
        uint256 fee  = (raw * feeBps) / 10_000;
        amountOut    = raw - fee;

        require(amountOut >= minAmountOut, "Router: slippage exceeded");

        // Mint toAsset to user
        IERC20Mintable toToken = IERC20Mintable(wrappedTokens[toAsset]);
        toToken.mint(msg.sender, amountOut);
        if (fee > 0) toToken.mint(feeCollector, fee);

        emit SwapExecuted(msg.sender, fromAsset, toAsset, amountIn, amountOut);
    }

    // ── Bridge Out ────────────────────────────────────────────────
    // Burns wrapped token. Relayer watches this event and releases
    // real asset on the destination chain.
    function bridgeOut(
        string  calldata asset,
        uint256          amount,
        string  calldata destinationAddress
    ) external nonReentrant {
        require(supportedAssets[asset], "Router: asset not supported");
        require(amount > 0,             "Router: zero amount");

        IERC20Mintable token = IERC20Mintable(wrappedTokens[asset]);
        token.burn(msg.sender, amount);

        uint256 fee       = (amount * feeBps) / 10_000;
        uint256 netAmount = amount - fee;

        emit BridgeOut(msg.sender, asset, netAmount, destinationAddress);
    }

    // ── View ──────────────────────────────────────────────────────
    function getQuote(
        string calldata fromAsset,
        string calldata toAsset,
        uint256         amountIn
    ) external view returns (uint256 amountOut, uint256 fee) {
        uint256 fromPrice = oracle.getPrice(fromAsset);
        uint256 toPrice   = oracle.getPrice(toAsset);
        if (fromPrice == 0 || toPrice == 0) return (0, 0);
        uint256 raw = (amountIn * fromPrice) / toPrice;
        fee       = (raw * feeBps) / 10_000;
        amountOut = raw - fee;
    }
}

contracts/AYRToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

// ============================================================
// AETHYR Native Token
// Fixed supply: 21,000,078 — matches genesis alloc
// ============================================================
contract AYRToken {
    string  public constant name     = "Aethyr";
    string  public constant symbol = "AYR";
    uint8   public constant decimals = 18;
    uint256 public constant totalSupply = 21_000_078 * 10**18;

    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);

    constructor() {
        balanceOf[msg.sender] = totalSupply;
        emit Transfer(address(0), msg.sender, totalSupply);
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        _transfer(msg.sender, to, amount);
        return true;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        emit Approval(msg.sender, spender, amount);
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        require(allowance[from][msg.sender] >= amount, "AYR: insufficient allowance");
        allowance[from][msg.sender] -= amount;
        _transfer(from, to, amount);
        return true;
    }

    function _transfer(address from, address to, uint256 amount) internal {
        require(to != address(0), "AYR: zero address");
        require(balanceOf[from] >= amount, "AYR: insufficient balance");
        balanceOf[from] -= amount;
        balanceOf[to]   += amount;
        emit Transfer(from, to, amount);
    }
}

contracts/BridgeLock.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract BridgeLock {
    address public owner;
    bool    public paused;

    event Locked(address indexed sender, uint256 amount);

    modifier onlyOwner() { require(msg.sender == owner, "Not owner"); _; }
    modifier notPaused() { require(!paused, "Paused"); _; }

    constructor() { owner = msg.sender; }

    function lock() external payable notPaused {
        require(msg.value > 0, "Zero amount");
        emit Locked(msg.sender, msg.value);
    }

    function pause() external onlyOwner { paused = true; }
    function unpause() external onlyOwner { paused = false; }
    function withdraw(address payable to, uint256 amount) external onlyOwner {
        require(address(this).balance >= amount, "Insufficient");
        to.transfer(amount);
    }

    receive() external payable { if (msg.value > 0) emit Locked(msg.sender, msg.value); }
}

contracts/UTXORegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

// ================================================================
// UTXORegistry — Bitcoin Containment Protocol
//
// Tracks Bitcoin UTXOs that have been activated as native AYR
// objects. The Bitcoin UTXO stays on Bitcoin — this contract
// records that it has been claimed and extended into AYR's state.
//
// FUNCTION SIGNATURES (must match utxo_native.js hardcoded selectors):
//   activateUTXO(bytes32,uint16,address,uint256)  → selector: a4f17e42
//   deactivateUTXO(bytes32,uint16)                → selector: c3f44c5a
//
// Access:
//   - Only authorized relayers can activate/deactivate.
//   - Owner can add/remove relayers.
//   - Anyone can query UTXO status.
// ================================================================

contract UTXORegistry {

    address public owner;

    struct UTXO {
        address owner;       // AYR address that activated this UTXO
        uint256 valueSats;   // Value in satoshis (stays on Bitcoin)
        uint64  activatedAt; // Block number when activated
        bool    active;      // false = deactivated (spent on Bitcoin)
    }

    // txid ++ vout → UTXO
    mapping(bytes32 => UTXO) public utxos;
    // Authorized relayers (node's hot wallet)
    mapping(address => bool) public relayers;
    // Total active UTXOs
    uint256 public activeCount;
    // Total satoshis contained (informational)
    uint256 public totalSats;

    event UTXOActivated(
        bytes32 indexed txid,
        uint16  indexed vout,
        address         owner,
        uint256         valueSats,
        uint256         blockNumber
    );
    event UTXODeactivated(
        bytes32 indexed txid,
        uint16  indexed vout,
        address         owner,
        string          reason
    );
    event RelayerUpdated(address relayer, bool status);

    modifier onlyOwner() {
        require(msg.sender == owner, "UTXORegistry: not owner");
        _;
    }

    modifier onlyRelayer() {
        require(relayers[msg.sender] || msg.sender == owner, "UTXORegistry: not relayer");
        _;
    }

    constructor(address _owner) {
        owner = _owner;
        relayers[_owner] = true;
    }

    // ── Admin ──────────────────────────────────────────────────────

    function setRelayer(address relayer, bool status) external onlyOwner {
        relayers[relayer] = status;
        emit RelayerUpdated(relayer, status);
    }

    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "UTXORegistry: zero address");
        owner = newOwner;
    }

    // ── Internal key ──────────────────────────────────────────────

    function _key(bytes32 txid, uint16 vout) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked(txid, vout));
    }

    // ── Core: Activate ────────────────────────────────────────────
    // Called by the AYR node after full SPV verification.
    // selector: keccak256("activateUTXO(bytes32,uint16,address,uint256)")[0:4] = a4f17e42
    //
    // Parameters:
    //   txid       — Bitcoin transaction ID (bytes32, big-endian)
    //   vout       — Output index
    //   owner      — AYR address receiving this UTXO as a native object
    //   valueSats  — Value in satoshis (read-only, stays on Bitcoin)
    function activateUTXO(
        bytes32 txid,
        uint16  vout,
        address utxoOwner,
        uint256 valueSats
    ) external onlyRelayer {
        bytes32 key = _key(txid, vout);
        require(!utxos[key].active, "UTXORegistry: already active");
        require(utxoOwner != address(0), "UTXORegistry: zero owner");
        require(valueSats > 0, "UTXORegistry: zero value");

        utxos[key] = UTXO({
            owner:       utxoOwner,
            valueSats:   valueSats,
            activatedAt: uint64(block.number),
            active:      true
        });

        activeCount++;
        totalSats += valueSats;

        emit UTXOActivated(txid, vout, utxoOwner, valueSats, block.number);
    }

    // ── Core: Deactivate ──────────────────────────────────────────
    // Called when the UTXO is detected as spent on Bitcoin.
    // The double-spend watchdog in utxo_native.js triggers this.
    // selector: keccak256("deactivateUTXO(bytes32,uint16)")[0:4] = c3f44c5a
    function deactivateUTXO(
        bytes32 txid,
        uint16  vout
    ) external onlyRelayer {
        bytes32 key = _key(txid, vout);
        UTXO storage u = utxos[key];
        require(u.active, "UTXORegistry: not active");

        address prevOwner = u.owner;
        totalSats -= u.valueSats;
        u.active = false;
        activeCount--;

        emit UTXODeactivated(txid, vout, prevOwner, "spent on Bitcoin");
    }

    // ── Views ─────────────────────────────────────────────────────

    function isActive(bytes32 txid, uint16 vout) external view returns (bool) {
        return utxos[_key(txid, vout)].active;
    }

    function getUTXO(bytes32 txid, uint16 vout) external view returns (
        address utxoOwner,
        uint256 valueSats,
        uint64  activatedAt,
        bool    active
    ) {
        UTXO storage u = utxos[_key(txid, vout)];
        return (u.owner, u.valueSats, u.activatedAt, u.active);
    }

    // Returns total BTC value contained in satoshis and BTC
    function totalContainedBTC() external view returns (uint256 sats, uint256 btcWhole, uint256 btcFrac) {
        sats     = totalSats;
        btcWhole = totalSats / 1e8;
        btcFrac  = totalSats % 1e8;
    }
}

